+.mega{
+  position:absolute;
+  left:-280px;
+  top:54px;
+  width:min(980px, calc(100vw - 44px));
+  background:rgba(255,255,255,.98);
+  border:1px solid rgba(10,22,40,.16);
+  border-radius:20px;
+  box-shadow:var(--shadow);
+  padding:20px;
+  transform-origin:top;
+  transform:translateY(10px) scale(.98);
+  opacity:0;
+  pointer-events:none;
+  transition:opacity .14s ease, transform .14s ease;
+}
+.has-mega[data-open="true"] .mega{opacity:1;transform:translateY(0) scale(1);pointer-events:auto}
+.mega-grid{display:grid;grid-template-columns:1.4fr 1fr;gap:18px}
+.mega h4{margin:0 0 10px;font-size:13px;letter-spacing:.12em;text-transform:uppercase;color:#344051}
+.mega-col{padding:14px;border-radius:16px;background:linear-gradient(180deg, #FFFFFF 0%, #F6F8FB 100%);border:1px solid rgba(10,22,40,.10)}
+.mega-links{display:grid;grid-template-columns:1fr 1fr;gap:6px 12px}
+.mega a{
+  display:flex;align-items:flex-start;gap:10px;
+  padding:10px 10px;
+  border-radius:14px;
+  text-decoration:none;
+  color:var(--ink);
+  border:1px solid transparent;
+}
+.mega a:hover{border-color:rgba(10,127,116,.22);background:rgba(10,127,116,.06)}
+.mega .icon{
+  width:30px;height:30px;border-radius:12px;
+  display:grid;place-items:center;
+  background:rgba(10,22,40,.06);
+  color:rgba(10,22,40,.72);
+  flex:0 0 auto;
+}
+.mega .meta{display:flex;flex-direction:column;gap:2px}
+.mega .title{font-weight:650;font-size:14px}
+.mega .desc{font-size:12px;color:var(--muted);line-height:1.35}
+
