+.mobile-drawer{
+  display:none;
+  position:fixed;
+  inset:0;
+  background:rgba(6,10,18,.58);
+  z-index:80;
+}
+.mobile-drawer[data-open="true"]{display:block}
+.drawer-panel{
+  width:min(420px, 90vw);
+  height:100%;
+  background:var(--navy);
+  color:#fff;
+  padding:18px 18px 24px;
+  border-right:1px solid rgba(255,255,255,.12);
+  box-shadow:var(--shadow);
+}
+.drawer-top{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}
+.drawer-close{background:transparent;border:1px solid rgba(255,255,255,.16);color:#fff;border-radius:12px;padding:10px 12px}
+.drawer-nav{display:flex;flex-direction:column;gap:8px}
+.drawer-link{
+  display:flex;align-items:center;justify-content:space-between;
+  padding:12px 12px;
+  border-radius:14px;
+  text-decoration:none;
+  background:rgba(255,255,255,.06);
+  border:1px solid rgba(255,255,255,.10);
+}
+.drawer-link:hover{background:rgba(255,255,255,.10)}
+.drawer-accordion{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.10);border-radius:14px;overflow:hidden}
+.acc-btn{width:100%;display:flex;align-items:center;justify-content:space-between;padding:12px 12px;background:transparent;border:0;color:#fff;font:inherit;font-weight:600}
+.acc-panel{max-height:0;overflow:hidden;transition:max-height .18s ease}
+.drawer-accordion[data-open="true"] .acc-panel{max-height:520px}
+.acc-links{display:flex;flex-direction:column;padding:0 10px 12px}
+.acc-links a{color:rgba(255,255,255,.86);text-decoration:none;padding:10px 10px;border-radius:12px}
+.acc-links a:hover{background:rgba(255,255,255,.08);color:#fff}
+
+/* Hero */
+.hero{
+  padding:92px 0 62px;
+  color:#fff;
+  background:
+    linear-gradient(180deg, rgba(10,22,40,.70) 0%, rgba(10,22,40,.78) 42%, rgba(10,22,40,.92) 100%),
+    url("https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=2200&q=70");
+  background-size:cover;
+  background-position:center;
+}
+.hero .grid{display:grid;grid-template-columns:1.2fr .8fr;gap:26px;align-items:end}
+.hero h1{font-size:56px;max-width:18ch}
+.hero p{font-size:18px;color:rgba(255,255,255,.82);max-width:62ch}
+.hero .panel{
+  background:rgba(255,255,255,.06);
+  border:1px solid rgba(255,255,255,.14);
+  border-radius:22px;
+  padding:18px;
+}
+.hero .panel .label{font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:rgba(255,255,255,.74)}
+.hero .panel .stat{font-size:28px;font-weight:760;margin-top:8px}
+.hero .panel .note{font-size:13px;color:rgba(255,255,255,.74)}
+
