+  border-color:rgba(10,127,116,.26);
+}
+.tab .name{font-weight:760;letter-spacing:-.01em}
+.tab .sub{font-size:13px;color:var(--muted);margin-top:4px}
+.tabpanel{padding:26px;position:relative;overflow:hidden}
+.tabpanel::before{
+  content:"";
+  position:absolute;inset:-2px;
+  background:
+    radial-gradient(600px 200px at 20% 0%, rgba(10,127,116,.14) 0%, transparent 60%),
