+  pointer-events:none;
+}
+.tabpanel > *{position:relative}
+.tabpanel h3{font-size:28px;margin-bottom:12px}
+
+/* Newsletter */
+.newsletter{
+  background:linear-gradient(135deg, var(--navy) 0%, var(--navy-2) 65%, #0B3B53 120%);
+  color:#fff;
+  border-top:1px solid rgba(255,255,255,.10);
+  border-bottom:1px solid rgba(255,255,255,.10);
+}
+.newsletter-inner{display:grid;grid-template-columns:1.25fr .75fr;gap:18px;align-items:center}
+.form{
+  display:flex;gap:10px;flex-wrap:wrap;justify-content:flex-end
+}
+.input{
+  flex:1 1 220px;
+  padding:12px 14px;
+  border-radius:999px;
+  border:1px solid rgba(255,255,255,.18);
+  background:rgba(255,255,255,.08);
+  color:#fff;
+  outline:none;
+}
+.input::placeholder{color:rgba(255,255,255,.62)}
+
+/* Footer */
+.footer{background:var(--navy);color:#fff}
+.footer-top{display:grid;grid-template-columns:1.2fr .8fr;gap:22px;padding:46px 0;border-bottom:1px solid rgba(255,255,255,.12)}
+.footer-links{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}
+.footer a{color:rgba(255,255,255,.78);text-decoration:none}
+.footer a:hover{color:#fff}
+.footer-bottom{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:18px 0;color:rgba(255,255,255,.66);font-size:12px}
+
+/* Components */
+.divider{height:1px;background:var(--border);margin:18px 0}
+.pillars .card-pad{padding:20px}
+.pillars h3{font-size:16px;margin-bottom:8px}
+
+.hero-simple{
+  padding:86px 0 56px;
+  color:#fff;
+  background:
+    linear-gradient(180deg, rgba(10,22,40,.64) 0%, rgba(10,22,40,.88) 100%),
+    url("https://images.unsplash.com/photo-1449247613801-ab06418e2861?auto=format&fit=crop&w=2200&q=70");
+  background-size:cover;
+  background-position:center;
+}
+.hero-simple h1{font-size:48px;max-width:20ch}
+.hero-simple p{color:rgba(255,255,255,.82);max-width:70ch;font-size:16px;margin-top:14px}
+
+.cap-grid .card-pad{padding:18px}
+.cap-grid h3{font-size:16px;margin-bottom:8px}
+
+.callout{
+  background:linear-gradient(180deg, #FFFFFF 0%, #F6F8FB 100%);
+  border:1px solid var(--border);
+  border-radius:22px;
+  padding:22px;
+}
+.callout strong{font-weight:800}
+
+.carousel{position:relative}
+.carousel-track{display:flex;gap:14px;overflow:hidden;scroll-behavior:smooth}
+.carousel-card{min-width:calc((100% - 28px)/3)}
+.carousel-controls{display:flex;gap:10px;justify-content:flex-end;margin-top:12px}
+.icon-btn{background:#fff;border:1px solid var(--border);border-radius:14px;padding:10px 12px;cursor:pointer}
+.icon-btn:hover{border-color:rgba(10,22,40,.22)}
+
+/* Responsive */
+@media (max-width: 980px){
+  .hero .grid{grid-template-columns:1fr}
+  .hero h1{font-size:44px}
+  .grid-3{grid-template-columns:1fr}
+  .grid-2{grid-template-columns:1fr}
+  .grid-4{grid-template-columns:repeat(2,1fr)}
+  .tabs{grid-template-columns:1fr}
+  .tablist{flex-direction:row;overflow:auto;padding-bottom:6px}
+  .tab{min-width:260px}
+  .newsletter-inner{grid-template-columns:1fr}
+  .form{justify-content:flex-start}
+  .carousel-card{min-width:calc((100% - 14px)/2)}
+  .mega{left:-220px}
+}
+
+@media (max-width: 780px){
+  .nav{display:none}
+  .nav-toggle{display:inline-flex}
+  .header-inner{height:68px}
+  .hero{padding:88px 0 54px}
+  .hero h1{font-size:40px}
+  .banner-inner{flex-direction:column;align-items:flex-start}
+  .footer-top{grid-template-columns:1fr}
+  .grid-4{grid-template-columns:1fr}
+  .carousel-card{min-width:100%}
+}
+
+@media (prefers-reduced-motion: reduce){
+  *{scroll-behavior:auto;transition:none !important}
+}
+
*** End Patch
PATCH

